/** The built-in set: one status per group, named by the group. */
export const DEFAULT_TASK_STATES: TaskState[] = TASK_STATUSES.map((group) => ({ id: group, group }))

export const MAX_TASK_STATES = 20
export const MAX_STATE_NAME = 40

/** The project's statuses in board order: by group, then as the project placed them. */
